    uint32_t& operator[](iox::range<uint64_t, 0, CLASS_HASH_ELEMENT_COUNT - 1> index) noexcept;
    const uint32_t& operator[](iox::range<uint64_t, 0, CLASS_HASH_ELEMENT_COUNT - 1> index) const noexcept;
